BEGIN;
ALTER TABLE workflow.closing_period ADD COLUMN IF NOT EXISTS current_step text NOT NULL DEFAULT 'PERIOD_OPENING' CHECK(current_step IN('PERIOD_OPENING','SCOPE_FREEZE','DATA_IMPORT','QUALITY_CONTROLS','RECONCILIATIONS','ASSET_VALIDATION','PROVISIONAL_CALCULATION','EXCEPTION_HANDLING','RESERVE_DCR_SIMULATIONS','FINANCE_VALIDATION','RISK_ALM_VALIDATION','SHARIA_COMPLIANCE_CONTROL','DELEGATED_APPROVAL','RUN_LOCKING','JOURNAL_GENERATION','CORE_BANKING_CREDIT','POST_PAYMENT_RECONCILIATION','STATEMENT_PRODUCTION','EVIDENCE_ARCHIVING')),ADD COLUMN IF NOT EXISTS workflow_status text NOT NULL DEFAULT 'DRAFT' CHECK(workflow_status IN('DRAFT','FED','ANOMALY','RECONCILED','CALCULATED','IN_VALIDATION','APPROVED','ACCOUNTED','PAID','CLOSED','CANCELLED','CORRECTED_BY_SUPPLEMENTARY_RUN'));
CREATE TABLE IF NOT EXISTS workflow.closing_step_event(event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),closing_id uuid NOT NULL REFERENCES workflow.closing_period(closing_id),step_number smallint NOT NULL CHECK(step_number BETWEEN 2 AND 19),previous_step text NOT NULL,resulting_step text NOT NULL,resulting_status text NOT NULL,actor_id text NOT NULL,evidence jsonb NOT NULL,idempotency_key text NOT NULL CHECK(length(idempotency_key)BETWEEN 16 AND 128),occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(closing_id,idempotency_key),UNIQUE(closing_id,step_number));
CREATE OR REPLACE FUNCTION workflow.guard_closing_step_event()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE expected_step text;current_no integer;BEGIN SELECT array_position(ARRAY['PERIOD_OPENING','SCOPE_FREEZE','DATA_IMPORT','QUALITY_CONTROLS','RECONCILIATIONS','ASSET_VALIDATION','PROVISIONAL_CALCULATION','EXCEPTION_HANDLING','RESERVE_DCR_SIMULATIONS','FINANCE_VALIDATION','RISK_ALM_VALIDATION','SHARIA_COMPLIANCE_CONTROL','DELEGATED_APPROVAL','RUN_LOCKING','JOURNAL_GENERATION','CORE_BANKING_CREDIT','POST_PAYMENT_RECONCILIATION','STATEMENT_PRODUCTION','EVIDENCE_ARCHIVING'],current_step)INTO current_no FROM workflow.closing_period WHERE closing_id=NEW.closing_id FOR UPDATE;expected_step:=(ARRAY['PERIOD_OPENING','SCOPE_FREEZE','DATA_IMPORT','QUALITY_CONTROLS','RECONCILIATIONS','ASSET_VALIDATION','PROVISIONAL_CALCULATION','EXCEPTION_HANDLING','RESERVE_DCR_SIMULATIONS','FINANCE_VALIDATION','RISK_ALM_VALIDATION','SHARIA_COMPLIANCE_CONTROL','DELEGATED_APPROVAL','RUN_LOCKING','JOURNAL_GENERATION','CORE_BANKING_CREDIT','POST_PAYMENT_RECONCILIATION','STATEMENT_PRODUCTION','EVIDENCE_ARCHIVING'])[current_no+1];IF NEW.resulting_step<>expected_step OR NEW.step_number<>current_no+1 THEN RAISE EXCEPTION 'Closing workflow cannot skip a step';END IF;IF NEW.resulting_step='PROVISIONAL_CALCULATION' AND COALESCE((NEW.evidence->>'qualityControlsGreen')::boolean,false)=false AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(COALESCE(NEW.evidence->'blockingAnomalyIds','[]'))a WHERE NOT(COALESCE(NEW.evidence->'acceptedRiskReferences','[]')?a.value))THEN RAISE EXCEPTION 'Provisional calculation blocked by unaccepted quality anomalies';END IF;RETURN NEW;END;$$;
DROP TRIGGER IF EXISTS closing_step_sequence_guard ON workflow.closing_step_event;CREATE TRIGGER closing_step_sequence_guard BEFORE INSERT ON workflow.closing_step_event FOR EACH ROW EXECUTE FUNCTION workflow.guard_closing_step_event();
CREATE OR REPLACE FUNCTION workflow.reject_closing_step_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Closing workflow history is append-only';END;$$;DROP TRIGGER IF EXISTS closing_step_event_immutable ON workflow.closing_step_event;CREATE TRIGGER closing_step_event_immutable BEFORE UPDATE OR DELETE ON workflow.closing_step_event FOR EACH ROW EXECUTE FUNCTION workflow.reject_closing_step_mutation();
COMMIT;
